UPDATE books
SET available_count = #{availableCount}
WHERE id = #{bookId}

UPDATE books
SET name = #{name}, author = #{author}, publisher = #{publisher}, publish_year = #{publishYear},
    description = #{description}, cover_url = #{coverUrl}, category_id = #{categoryId}
WHERE id = #{id}

mapper.select:
SELECT FROM books
name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY id DESC LIMIT #{offset}, #{size}
